// The planner's change log as feature code uses it: the reads, prune and bulk marker are `planner` calls
// (src/data/planner/changes.ts), the triggers that fill the log are generated by src/db/plan-triggers.ts.
// A planner reads the rows it has not read yet (changesSince) and later deletes exactly the rows it read (pruneChanges).
import { beginBulk, endBulk, loadChangeCursor, logChanged, pruneChanges as prune, readChanges, type ChangeCursor, type Changes } from "../data/planner/index.ts";
import { loadReviewedRefs } from "../data/review/index.ts";
import type { Db } from "../db/index.ts";

export { BULK_ROWS } from "../db/plan-triggers.ts";
export type { ChangeCursor, Changes };

/** What a full pass that starts now covers: the generation and every logged row. Read it in the pass's snapshot. */
export const changeCursor = loadChangeCursor;

/** What changed since `cursor`: the items to decide again, or `full`. Read it in the pass's snapshot. */
export const changesSince = readChanges;

/** Deletes the log rows `cursor` has read, and forgets them. */
export async function pruneChanges(db: Db, cursor: ChangeCursor): Promise<void> {
  await prune(db, cursor);
  cursor.seen.clear();
}

/** Logs the PRs with a review at `head` of `repo`: for a write the triggers cannot see (a file the fact loaders read beside the database). */
export async function logReviewedAt(db: Db, repo: string, head: string): Promise<void> {
  const refs = (await loadReviewedRefs(db, repo, head)).map((k) => ({ repo: k.slice(0, k.lastIndexOf("#")), number: Number(k.slice(k.lastIndexOf("#") + 1)) }));
  await logChanged(db, refs);
}

/** Handles inside a bulkWrites call, so a nested call joins the outer one's marker. */
const inBulk = new WeakSet<object>();

/**
 * Runs `fn` with the logging triggers off and takes one full-pass mark for `source`, in the caller's transaction or one of its
 * own. The marker exists only inside that transaction, so other connections never see the triggers off.
 */
export async function bulkWrites<T>(db: Db, source: string, fn: () => Promise<T>): Promise<T> {
  const own = !db.inTransaction();
  return await db.write(async () => {
    if (inBulk.has(db)) return await fn();
    inBulk.add(db);
    try {
      await beginBulk(db);
      const out = await fn();
      await endBulk(db, source);
      return out;
    } catch (e) {
      // A transaction of its own rolls the marker back; the caller's goes on, so the marker ends now. On Postgres a failed
      // statement has aborted the caller's transaction (or the savepoint around it, which undoes the marker), so this may fail.
      if (!own) await endBulk(db, source).catch(() => undefined);
      throw e;
    } finally {
      inBulk.delete(db);
    }
  });
}
